// HasUsageEvents applies the HasEdge predicate on the "usage_events" edge.
func HasUsageEvents() predicate.RunAttribution {
	return predicate.RunAttribution(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, UsageEventsTable, UsageEventsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUsageEventsWith applies the HasEdge predicate on the "usage_events" edge with a given conditions (other predicates).
func HasUsageEventsWith(preds ...predicate.UsageEvent) predicate.RunAttribution {
	return predicate.RunAttribution(func(s *sql.Selector) {
		step := newUsageEventsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RunAttribution) predicate.RunAttribution {
	return predicate.RunAttribution(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RunAttribution) predicate.RunAttribution {
	return predicate.RunAttribution(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RunAttribution) predicate.RunAttribution {
	return predicate.RunAttribution(sql.NotPredicates(p))
}
